            fieldtype: 'Data',
            label: __('Postal Code'),
            reqd: 0,
            depends_on: "eval:doc.mode == 'create'",
          },
          {
            fieldname: 'country',
            fieldtype: 'Link',
            label: __('Country'),
            options: 'Country',
            reqd: 0,
            depends_on: "eval:doc.mode == 'create'",
          },
        ],
        submitLabel: __('Save'),
      })

      if (!values) return

      if (values.mode === 'link') {
        await me.linkExistingAddress(values.existing_address, leadName)
      } else {
        await me.saveNewAddress(values, leadName)
      }
    } catch (e) {
      console.error('Dialog error:', e)
      toast.error(e?.message || __('Failed to open dialog'))
    }
  }

  async linkExistingAddress(addressName, leadName) {
    try {
      const address = await call(
        'frappe.client.get',
        {
          doctype: 'Address',
          name: addressName,
        }
      )

      const alreadyLinked = address.links && address.links.some(
        link => link.link_doctype === 'CRM Lead' && link.link_name === leadName
      )

      if (alreadyLinked) {
        toast.error(__('This address is already linked to this lead'))
        return
      }

      if (!address.links) {
        address.links = []
      }

      address.links.push({
        doctype: 'Dynamic Link',
        link_doctype: 'CRM Lead',
        link_name: leadName,
      })

      await call(
        'frappe.client.set_value',
        {
          doctype: 'Address',
          name: addressName,
          fieldname: 'links',
          value: address.links,
        }
      )

      toast.success(__('Address linked successfully'))
      await this.renderAddresses()
    } catch (e) {
      console.error('linkExistingAddress error:', e)
      toast.error(
        e?.messages?.[0] ||
        e?.message ||
        __('Failed to link address')
      )
    }
  }

  async saveNewAddress(values, leadName) {
    try {
      if (!values.address_title || !values.address_line1 || !values.city || !values.country) {
        toast.error(__('Please fill all required fields for creating new address'))
        return
      }

      const addressDoc = {
        doctype: 'Address',
        address_title: values.address_title,
        address_type: values.address_type,
        address_line1: values.address_line1,
        address_line2: values.address_line2,
        city: values.city,
        state: values.state,
        pincode: values.pincode,
        country: values.country,
        links: [
          {
            doctype: 'Dynamic Link',
            link_doctype: 'CRM Lead',
            link_name: leadName,
          },
        ],
      }

      await call(
        'frappe.client.insert',
        {
          doc: addressDoc,
        }
      )

      toast.success(__('Address created and linked'))
      await this.renderAddresses()
    } catch (e) {
      console.error('saveNewAddress error:', e)
      toast.error(
        e?.messages?.[0] ||
        e?.message ||
        __('Failed to create address')
      )
    }
  }

  async unlinkAddress(addressName, leadName) {
    const me = this

    try {
      const address = await call(
        'frappe.client.get',
        {
          doctype: 'Address',
          name: addressName,
        }
      )

      address.links = (address.links || []).filter(
        link => !(link.link_doctype === 'CRM Lead' && link.link_name === leadName)
      )

      await call(
        'frappe.client.set_value',
        {
          doctype: 'Address',
          name: addressName,
          fieldname: 'links',
          value: address.links,
        }
      )

      toast.success(__('Address unlinked'))
      await me.renderAddresses()
    } catch (e) {
      console.error('unlinkAddress error:', e)
      toast.error(
        e?.messages?.[0] ||
        e?.message ||
        __('Failed to unlink address')
      )
    }
  }
}

